// ── Section Dividers ─────────────────────────────────────────────────────
// Rules:
//   1. --- appears between every H2 section (but not before the first)
//   2. No --- between H3 sub-sections within the same H2

const raw     = $json.content ?? '';
const fixes   = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags   = Array.isArray($json.flags) ? [...$json.flags] : [];
let   changed = $json.changed ?? false;

if (!raw) return { ...$json, fixes, flags, changed };

// 1. Separate Frontmatter from Body
const fmMatch = raw.match(/^---[\r\n][\s\S]*?[\r\n]---[\r\n]/);
const fmEnd   = fmMatch ? fmMatch[0].length : 0;
const fm      = raw.slice(0, fmEnd);
const bodyIn  = raw.slice(fmEnd);

const lines = bodyIn.split('\n');
const out = [];
let h2Seen = false;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  const isH2 = /^## (?!#)/.test(line);
  const isH3 = /^### (?!#)/.test(line);

  if (isH2) {
    // Strip any trailing blanks and --- lines in any combination
    let stripping = true;
    while (stripping) {
      stripping = false;
      while (out.length > 0 && out[out.length - 1].trim() === '') { out.pop(); stripping = true; }
      while (out.length > 0 && /^(---|___|\*\*\*)$/.test(out[out.length - 1].trim())) { out.pop(); stripping = true; }
    }
    if (h2Seen) {
      out.push('');
      out.push('---');
      out.push('');
    } else {
      out.push('');
    }
    out.push(line);
    h2Seen = true;
  } else if (isH3) {
    let lookback = out.length - 1;
    while (lookback >= 0 && out[lookback].trim() === '') lookback--;
    if (lookback >= 0 && /^(---|___|\*\*\*)$/.test(out[lookback].trim())) {
      out.splice(lookback, out.length - lookback);
      out.push('');
    }
    out.push(line);
  } else {
    out.push(line);
  }
}

const bodyOut = out.join('\n');
if (bodyOut !== bodyIn) {
  changed = true;
  fixes.push('Fixed H2 section dividers (--- between H2s; removed --- before H3s)');
}

return {
  ...$json,
  content: fm + bodyOut,
  fixes,
  flags,
  changed,
};

// ── H1 Heading ───────────────────────────────────────────────────────────
// Rules:
//   1. No H1 → insert `# Filename` at top of body
//   2. Exactly one H1, correct text, already at top → no change
//   3. Exactly one H1, wrong text → correct text, ensure at top
//   4. Exactly one H1, correct text, not at top → move to top
//   5. Multiple H1s → correct first to match filename, move to top,
//                      downgrade all remaining H1s to H2
//
// "Top" = first non-blank line of the body (after frontmatter).
// Whitespace normalisation is deferred to a later step — this node
// does not touch blank lines except when inserting a missing H1.

const filePath = $json.filePath ?? '';
const filename  = $json.filename ?? filePath.split('/').pop().replace(/\.md$/, '');
const raw       = $json.content ?? '';
const fixes     = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags     = Array.isArray($json.flags) ? [...$json.flags] : [];
let   changed   = $json.changed ?? false;

if (!raw) return { ...$json, fixes, flags, changed };

// ── Split frontmatter from body ───────────────────────────────────────────
// FM is the opening --- block; never scan it for H1s.
const fmMatch = raw.match(/^---[\r\n][\s\S]*?[\r\n]---[\r\n]/);
const fmEnd   = fmMatch ? fmMatch[0].length : 0;
const fm      = raw.slice(0, fmEnd);
const rawBody = raw.slice(fmEnd);

// ── Work line-by-line on the body ────────────────────────────────────────
const lines      = rawBody.split('\n');
const expectedH1 = `# ${filename}`;

// All line indices that are H1s (lines starting with exactly '# ')
const h1Indices = lines.reduce((acc, line, i) => {
  if (/^# /.test(line)) acc.push(i);
  return acc;
}, []);

// First non-blank line index
const firstContentIdx = lines.findIndex(l => l.trim() !== '');

let newLines = [...lines];

if (h1Indices.length === 0) {
  // Rule 1: No H1 — insert at top of body
  newLines.unshift(expectedH1);
  fixes.push(`Inserted missing H1: ${expectedH1}`);
  changed = true;

} else if (h1Indices.length === 1) {
  const idx    = h1Indices[0];
  const atTop  = idx === firstContentIdx;
  const textOk = lines[idx] === expectedH1;

  if (atTop && textOk) {
    // Rule 2: Already perfect — nothing to do

  } else {
    const originalText = lines[idx].replace(/^# /, '');
    newLines.splice(idx, 1);
    newLines.unshift(expectedH1);

    if (!atTop && textOk) {
      fixes.push(`Moved H1 to top of body`);
    } else if (atTop && !textOk) {
      fixes.push(`Corrected H1 text: "${originalText}" → "${filename}"`);
    } else {
      fixes.push(`Corrected H1 text and moved to top: "${originalText}" → "${filename}"`);
    }
    changed = true;
  }

} else {
  // Rule 5: Multiple H1s — downgrade all but first to H2, correct first, move to top
  const [first, ...rest] = h1Indices;

  for (const idx of [...rest].reverse()) {
    const text = newLines[idx].replace(/^# /, '');
    newLines[idx] = `## ${text}`;
    fixes.push(`Downgraded duplicate H1 to H2: "${text}"`);
  }

  const originalText = newLines[first].replace(/^# /, '');
  if (newLines[first] !== expectedH1) {
    fixes.push(`Corrected H1 text: "${originalText}" → "${filename}"`);
    newLines[first] = expectedH1;
  }

  const currentFirstContent = newLines.findIndex(l => l.trim() !== '');
  if (first !== currentFirstContent) {
    newLines.splice(first, 1);
    newLines.unshift(expectedH1);
    fixes.push(`Moved H1 to top of body`);
  }

  changed = true;
}

return {
  ...$json,
  filePath,
  filename,
  fileType: $json.fileType,
  content:  fm + newLines.join('\n'),
  fixes,
  flags,
  changed,
};

// ── Step 1: Frontmatter ──────────────────────────────────────────────────
const SCHEMA_ORDER = {
  project:  ['type', 'project', 'area', 'status'],
  research: ['type', 'project', 'area', 'status'],
  log:      ['type', 'project', 'area'],
  wiki:     ['type', 'project', 'area'],
  meta:     ['type', 'project', 'area'],
};

const FLAG_IF_MISSING = ['project'];
const LINTER_KEYS = ['date created', 'date modified'];
const PREFIX_TO_TYPE = {
  Project:    'project',
  Research:   'research',
  Wiki:       'wiki',
  Log:        'log',
  Meta:       'meta',
  Area:       'area',
  Prompt:     'meta',
  Cheatsheet: 'wiki',
};
const PREFIX_RE = /^([A-Za-z]+)\s*[\u2013\-]/;

function parseFM(content) {
  const match = content.match(/^---\s*[\r\n]+([\s\S]*?)---\s*[\r\n]+/);
  if (!match) return null;
  const raw   = match[0];
  const pairs = [];
  for (const line of match[1].split('\n')) {
    if (!line.trim()) continue;
    const colon = line.indexOf(':');
    if (colon === -1) continue;
    const key   = line.slice(0, colon).trim();
    const value = line.slice(colon + 1).trim();
    if (key) pairs.push({ key, value });
  }
  return { raw, pairs, end: raw.length };
}

function buildFM(pairs) {
  const lines = pairs.map(p => `${p.key}: ${p.value}`);
  return `---\n${lines.join('\n')}\n---\n`;
}

const filePath = $json.filePath ?? '';
const filename = filePath.split('/').pop().replace(/\.md$/, '');
const fixes    = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags    = Array.isArray($json.flags) ? [...$json.flags] : [];

if (!filePath) return { ...$json, fixes, flags, changed: false };

// ── Bootstrap missing frontmatter block ──────────────────────────────────
// If the file has no frontmatter at all, insert an empty stub so the rest
// of this node can populate it. Linter will add date created / date modified
// on the next file open in Obsidian.
let workingContent = $json.content ?? '';
if (!workingContent) return { ...$json, fixes, flags, changed: false };

let fm = parseFM(workingContent);
if (!fm) {
  workingContent = '---\n---\n' + workingContent;
  fm = parseFM(workingContent);
  if (!fm) return { ...$json, fixes, flags, changed: false }; // shouldn't happen
  fixes.push('Inserted missing frontmatter block');
}

const pairs = fm.pairs.map(p => ({ ...p }));
const getPairsByKey = () => Object.fromEntries(pairs.map(p => [p.key, p]));

let fmDirty = fixes.some(f => f === 'Inserted missing frontmatter block');
const prefixMatch = filename.match(PREFIX_RE);
const prefixKey   = prefixMatch ? (Object.keys(PREFIX_TO_TYPE).find(k => k.toLowerCase() === prefixMatch[1].toLowerCase()) ?? null) : null;
const prefixType  = prefixKey ? PREFIX_TO_TYPE[prefixKey] : null;

let pairsByKey = getPairsByKey();
const fmType   = pairsByKey['type']?.value ?? null;

let fileType;
if (prefixType) {
  if (!fmType) {
    pairs.unshift({ key: 'type', value: prefixType });
    fixes.push(`Inserted missing frontmatter key: type: ${prefixType}`);
    fmDirty = true;
  } else if (fmType !== prefixType) {
    const p = pairs.find(p => p.key === 'type');
    if (p) p.value = prefixType;
    fixes.push(`Corrected type: ${fmType} -> ${prefixType}`);
    fmDirty = true;
  }
  fileType = prefixType;
} else {
  fileType = fmType;
}

pairsByKey = getPairsByKey();

function slugify(str) {
  return str
    .replace(/^(?:Project|Research|Wiki|Log|Meta|Area|Cheatsheet)\s*[\u2013\-]\s*/i, '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function deriveProjectSlug(filePath, allKnownFiles, areaMap) {
  const parts  = filePath.split('/');
  const folder = parts.length > 1 ? parts.slice(0, -1).join('/') : null;
  const ownFilename = parts[parts.length - 1].replace(/\.md$/, '');

  // Collect area/category folder names to exclude from slug derivation
  const categoryFolderNames = new Set(
    Object.keys(areaMap ?? {}).map(k => k.toLowerCase())
  );

  if (folder && Array.isArray(allKnownFiles)) {
    // Only assign sibling slug if exactly one Project – file exists in the folder
    const siblings = allKnownFiles.filter(f => {
      const fParts  = f.split('/');
      const fFolder = fParts.length > 1 ? fParts.slice(0, -1).join('/') : null;
      const fName   = fParts[fParts.length - 1];
      return fFolder === folder && /^Project\s*[\u2013\-]/i.test(fName);
    });
    if (siblings.length === 1) return slugify(siblings[0].split('/').pop().replace(/\.md$/, ''));
    // Multiple siblings — ambiguous, don't assign
  }

  if (folder) {
    const folderName = folder.split('/').pop();
    const folderLower = (folderName ?? '').toLowerCase();
    // Exclude known top-level structural folders and area/category names
    const isStructural = /^(projects|library|archive|overview|scratchpad)$/i.test(folderName);
    const isCategory   = categoryFolderNames.has(folderLower);
    if (folderName && !isStructural && !isCategory) {
      return slugify(folderName);
    }
  }

  if (folder && /^Projects$/i.test(folder)) return slugify(ownFilename);
  return null;
}

const allKnownFiles = $json.allKnownFiles ?? [];
const schemaKeys = fileType ? (SCHEMA_ORDER[fileType] ?? []) : [];

// ── Archive status normalisation ─────────────────────────────────────────
// Files under Archive/:
//   - project/research: ensure status: archive (insert if missing, correct if wrong)
//   - other types: correct status to archive if the key is already present
if (filePath.startsWith('Archive/')) {
  const statusPair = pairs.find(p => p.key === 'status');
  const schemaHasStatus = schemaKeys.includes('status');
  if (statusPair) {
    if (statusPair.value !== 'archive') {
      statusPair.value = 'archive';
      fixes.push(`Set status: archive (file is in Archive/)`);
      fmDirty = true;
    }
  } else if (schemaHasStatus) {
    pairs.push({ key: 'status', value: 'archive' });
    fixes.push(`Inserted status: archive (file is in Archive/)`);
    fmDirty = true;
  }
}

for (const key of schemaKeys) {
  if (pairsByKey[key]) continue;
  if (key === 'status') {
    pairs.push({ key: 'status', value: 'active' });
    fixes.push('Inserted missing frontmatter key: status: active');
    fmDirty = true;
  } else if (key === 'project') {
    let derived = null;
    let derivedSource = '';
    if (fileType === 'project') {
      // Project files are their own slug — derive from own filename
      derived = slugify(filename);
      derivedSource = 'own filename';
    } else if ($json.siblingProjectSlug) {
      derived = $json.siblingProjectSlug;
      derivedSource = 'sibling project file';
    } else {
      derived = deriveProjectSlug(filePath, allKnownFiles, $json.areaMap ?? {});
      derivedSource = 'hierarchy';
    }
    if (derived) {
      pairs.push({ key: 'project', value: derived });
      fixes.push(`Inserted missing frontmatter key: project: ${derived} (derived from ${derivedSource})`);
      fmDirty = true;
    } else if (!filePath.startsWith('Archive/')) {
      flags.push('Missing frontmatter key: project — could not derive, manual review needed');
    }
    // Archive files: silently skip if derivation fails
  } else if (key === 'area') {
    if ($json.siblingProjectArea) {
      pairs.push({ key: 'area', value: $json.siblingProjectArea });
      fixes.push(`Inserted missing frontmatter key: area: ${$json.siblingProjectArea} (from sibling project file)`);
      fmDirty = true;
    } else {
      // Try to derive area from folder name using areaMap
      const areaMap = $json.areaMap ?? {};
      const pathParts = filePath.split('/');
      // Second segment is the area folder (e.g. Library/HomeLab/... → HomeLab)
      const areaFolder = pathParts.length >= 2 ? pathParts[1] : null;
      const areaEntry = areaFolder ? areaMap[areaFolder] : null;
      if (areaEntry) {
        pairs.push({ key: 'area', value: areaEntry.slug });
        fixes.push(`Inserted missing frontmatter key: area: ${areaEntry.slug} (derived from folder path)`);
        fmDirty = true;
      } else if (!filePath.startsWith('Archive/')) {
        flags.push('Missing frontmatter key: area');
      }
      // Archive files: silently skip missing area
    }
  } else if (FLAG_IF_MISSING.includes(key)) {
    flags.push(`Missing frontmatter key: ${key}`);
  }
  pairsByKey = getPairsByKey();
}

let newContent = workingContent;
if (fmDirty) {
  const linterPairs = pairs.filter(p => LINTER_KEYS.includes(p.key));
  const schemaPairs = schemaKeys.filter(k => pairsByKey[k]).map(k => pairsByKey[k]);
  const extraPairs  = pairs.filter(p => !schemaKeys.includes(p.key) && !LINTER_KEYS.includes(p.key));
  newContent = buildFM([...schemaPairs, ...extraPairs, ...linterPairs]) + workingContent.slice(fm.end);
}

return {
  ...$json,
  fileType,
  content:  newContent,
  fixes,
  flags,
  changed:  fmDirty || ($json.changed ?? false),
};

// ── Intro Heading ────────────────────────────────────────────────────────
// Rules:
//   project → Brief
//   research/wiki → Overview
//   log → Summary
//   meta → null (skip)
//   If ANY heading (H2-H4) matches a synonym (Description, About, etc.) → elevate to H2 and rename to canonical.
//   Else if no H2s exist → flag.

const INTRO_HEADING = {
  project: 'Brief', research: 'Overview', wiki: 'Overview', log: 'Summary', meta: null,
};

const BAD_INTROS = ['Description', 'About', 'Introduction', 'Background', 'Summary', 'Brief', 'Overview'];

const raw      = $json.content ?? '';
const fileType = $json.fileType ?? null;
const fixes    = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags    = Array.isArray($json.flags) ? [...$json.flags] : [];
let   changed  = $json.changed ?? false;

const expected = fileType ? (INTRO_HEADING[fileType] ?? null) : null;

if (!raw || !expected) return { ...$json, fixes, flags, changed };

// 1. Separate FM from Body
const fmMatch = raw.match(/^---[\r\n][\s\S]*?[\r\n]---[\r\n]/);
const fmEnd   = fmMatch ? fmMatch[0].length : 0;
const fm      = raw.slice(0, fmEnd);
const body    = raw.slice(fmEnd);

// 2. Search for ANY heading (H2-H4) that looks like an intro synonym
const introRegex = new RegExp(`^#{2,4} (${BAD_INTROS.join('|')})\\s*$`, 'mi');
const introMatch = body.match(introRegex);

if (introMatch) {
    const foundHeading = introMatch[0].trim();
    const canonical    = `## ${expected}`;

    if (foundHeading !== canonical) {
        const newBody = body.replace(introRegex, canonical);
        fixes.push(`Standardised intro heading: "${foundHeading}" → "${canonical}"`);
        return {
            ...$json,
            content: fm + newBody,
            fixes, flags, changed: true
        };
    }
} else {
    // 3. No synonym found. Scan for the canonical heading explicitly.
    const lines = body.split('\n');
    const canonicalH2 = `## ${expected}`;

    // Find index of canonical H2 anywhere in the body
    const canonicalIdx = lines.findIndex(l => l.trim() === canonicalH2);

    // Find the first meaningful line after the H1 + Related block
    // Skip: H1 lines, **Related** header, [[wikilink]] lines, blanks
    const relatedHeaderRe = /^\*\*Related(?::|)\*\*/i;
    let scanIdx = 0;
    while (scanIdx < lines.length && (/^# /.test(lines[scanIdx]) || lines[scanIdx].trim() === '')) scanIdx++;
    let inRelated = false;
    while (scanIdx < lines.length) {
      const l = lines[scanIdx].trim();
      if (relatedHeaderRe.test(l)) { inRelated = true; scanIdx++; continue; }
      if (inRelated && (l === '' || (l.startsWith('[[') && l.endsWith(']]')))) { scanIdx++; continue; }
      break;
    }
    const firstMeaningfulLine = lines[scanIdx]?.trim() ?? '';
    const firstMeaningfulIsH2 = /^## /.test(firstMeaningfulLine);

    if (canonicalIdx !== -1) {
      // Canonical heading exists somewhere in the body
      if (lines[scanIdx]?.trim() === canonicalH2) {
        // Already in the correct position — no action needed
      } else {
        // Exists but is buried — flag for manual review
        flags.push(`Intro heading "${canonicalH2}" exists but is not in intro position — manual review needed`);
      }
    } else if (!firstMeaningfulIsH2 && firstMeaningfulLine !== '') {
      // No canonical heading, orphaned paragraph before first H2 — insert heading
      lines.splice(scanIdx, 0, canonicalH2);
      fixes.push(`Inserted missing intro heading "${canonicalH2}" before orphaned intro paragraph`);
      return {
        ...$json,
        content: fm + lines.join('\n'),
        fixes, flags, changed: true,
      };
    } else if (firstMeaningfulIsH2) {
      // First H2 exists but isn't canonical and wasn't a synonym
      const firstH2Text = firstMeaningfulLine.replace(/^## /, '').trim();
      flags.push(`Intro heading is "## ${firstH2Text}" — expected "${canonicalH2}" for type:${fileType}. Manual review needed.`);
    } else {
      flags.push(`No intro section found (searched for ${BAD_INTROS.join('/')}) — cannot verify`);
    }
}

return { ...$json, fixes, flags, changed };

// Task Backlinks
// project/research: any ## Tasks heading must be formatted as:
//   ## Tasks - Doc Name [[Doc Name|up-arrow]]
// Auto-fix bare ## Tasks, ## Tasks - Name (no backlink), or wrong name.
// log/wiki: flag if any task list items are present.
// area/meta: skip.

const raw      = $json.content ?? '';
const filePath = $json.filePath ?? '';
const filename = $json.filename ?? filePath.split('/').pop().replace(/\.md$/, '');
const fileType = $json.fileType ?? null;
const fixes    = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags    = Array.isArray($json.flags) ? [...$json.flags] : [];
let   changed  = $json.changed ?? false;

if (!raw || fileType === 'area' || fileType === 'meta') {
  return { ...$json, fixes, flags, changed };
}

if (fileType === 'log' || fileType === 'wiki') {
  if (/^- \[[ x]\]/m.test(raw)) {
    flags.push('Tasks found in type:' + fileType + ' file -- log/wiki files should not contain tasks');
  }
  return { ...$json, fixes, flags, changed };
}

// project / research
const EN_DASH  = String.fromCharCode(0x2013);
const UP_ARROW = String.fromCharCode(0x2197) + String.fromCharCode(0xFE0F);
const correctHeading = '## Tasks ' + EN_DASH + ' ' + filename + ' [[' + filename + '|' + UP_ARROW + ']]';

// Match any ## Tasks line
const taskHeadingRe = /^## Tasks(?:[^\n]*)?$/gm;

let taskHeadingFound = false;
const newContent = raw.replace(taskHeadingRe, function(match) {
  taskHeadingFound = true;
  if (match.trim() === correctHeading) return match;
  fixes.push('Fixed Tasks heading: "' + match.trim() + '" -> "' + correctHeading + '"');
  changed = true;
  return correctHeading;
});

return {
  ...$json,
  content: taskHeadingFound ? newContent : raw,
  fixes,
  flags,
  changed,
};

// ── Task Position ─────────────────────────────────────────────────────────
// Project and research files: Tasks section must appear immediately after
// the intro section (Brief / Overview). If found elsewhere, extract and
// reinsert. Section dividers are stripped here — the Section Dividers node
// runs after this and rebuilds them cleanly.
// All other types: skip.

const INTRO_HEADING = {
  project: 'Brief', research: 'Overview', wiki: 'Overview', log: 'Summary', meta: null,
};

const raw      = $json.content ?? '';
const fileType = $json.fileType ?? null;
const fixes    = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags    = Array.isArray($json.flags) ? [...$json.flags] : [];
let   changed  = $json.changed ?? false;

if (!raw || !['project', 'research'].includes(fileType)) {
  return { ...$json, fixes, flags, changed };
}

// Split FM from body
const fmMatch = raw.match(/^---[\r\n][\s\S]*?[\r\n]---[\r\n]/);
const fmEnd   = fmMatch ? fmMatch[0].length : 0;
const fm      = raw.slice(0, fmEnd);
const body    = raw.slice(fmEnd);

const introName = INTRO_HEADING[fileType];
if (!introName) return { ...$json, fixes, flags, changed };

// Find all H2 headings in the body
const h2Re      = /^## .+$/gm;
const h2Matches = [...body.matchAll(h2Re)];
if (h2Matches.length < 2) return { ...$json, fixes, flags, changed };

const tasksIdx = h2Matches.findIndex(m => /^## Tasks/.test(m[0]));
const introIdx = h2Matches.findIndex(m => m[0].includes(`## ${introName}`));

// Nothing to do if Tasks is missing, intro is missing, or already in position
if (tasksIdx === -1 || introIdx === -1 || tasksIdx === introIdx + 1) {
  return { ...$json, fixes, flags, changed };
}

// Slice body into per-section chunks starting at each H2
const preamble = body.slice(0, h2Matches[0].index);
const sections = h2Matches.map((m, i) => {
  const start = m.index;
  const end   = i + 1 < h2Matches.length ? h2Matches[i + 1].index : body.length;
  return body.slice(start, end);
});

// Strip leading dividers and blank lines from each section
// Section Dividers node will rebuild these correctly afterwards
const cleanSections = sections.map(s =>
  s.replace(/^(?:\n*---\n+)+/, '').replace(/^\n+/, '')
);

// Extract Tasks block and reinsert immediately after intro
const tasksBlock = cleanSections.splice(tasksIdx, 1)[0];
const adjustedIntroIdx = tasksIdx < introIdx ? introIdx - 1 : introIdx;
cleanSections.splice(adjustedIntroIdx + 1, 0, tasksBlock);

const rebuiltBody = preamble + cleanSections.join('\n');
const newContent  = fm + rebuiltBody;

if (newContent !== raw) {
  fixes.push(`Moved Tasks section to immediately after ## ${introName}`);
  changed = true;
}

return {
  ...$json,
  content: newContent,
  fixes,
  flags,
  changed,
};

// ── Related Section ──────────────────────────────────────────────────────
// Rules:
//   1. Related section missing → insert header immediately after H1
//      then apply rule 2.
//   2. Related section present but empty:
//      a. If project: frontmatter exists, auto-insert [[Project – Name]] link.
//         Derive project index filename from allKnownFiles (sibling Project – file)
//         or fall back to constructing from project slug.
//      b. If still empty after (a) → flag: Related section is empty.
//   3. Related section present with at least one link → no action.
//
// Applies to: project, research, wiki, log, meta.
// Related section format:
//   **Related**
//   [[Link 1]]
//   [[Link 2]]
// Sits immediately after H1, before any H2.

const raw          = $json.content ?? '';
const filePath     = $json.filePath ?? '';
const fileType     = $json.fileType ?? null;
const fixes        = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags        = Array.isArray($json.flags) ? [...$json.flags] : [];
const allKnownFiles = Array.isArray($json.allKnownFiles) ? $json.allKnownFiles : [];
let   changed      = $json.changed ?? false;

// Skip area files — they don't use Related
if (!raw || fileType === 'area') return { ...$json, fixes, flags, changed };

// ── Split FM from body ────────────────────────────────────────────────────
const fmMatch = raw.match(/^---[\r\n][\s\S]*?[\r\n]---[\r\n]/);
const fmEnd   = fmMatch ? fmMatch[0].length : 0;
const fm      = raw.slice(0, fmEnd);
const body    = raw.slice(fmEnd);
const lines   = body.split('\n');

// ── Find project index link if possible ──────────────────────────────────
function findProjectIndexName(filePath, allKnownFiles) {
  const parts  = filePath.split('/');
  const folder = parts.length > 1 ? parts.slice(0, -1).join('/') : null;
  if (!folder) return null;

  // Only assign if exactly one Project – file exists in the folder
  const siblings = allKnownFiles.filter(f => {
    const fParts  = f.split('/');
    const fFolder = fParts.length > 1 ? fParts.slice(0, -1).join('/') : null;
    const fName   = fParts[fParts.length - 1];
    return fFolder === folder && /^Project\s*[\u2013\-]/i.test(fName);
  });
  if (siblings.length === 1) return siblings[0].split('/').pop().replace(/\.md$/, '');
  return null;
}

// Extract project slug from frontmatter
const projectSlugMatch = fm.match(/^project:\s*(.+)$/m);
const projectSlug = projectSlugMatch ? projectSlugMatch[1].trim() : null;

// Best project index name: siblingPath (already resolved) > allKnownFiles search
const siblingPath = $json.siblingPath ?? null;
const projectIndexName = siblingPath
  ? siblingPath.split('/').pop().replace(/\.md$/, '')
  : findProjectIndexName(filePath, allKnownFiles);

// ── Parse existing Related section ───────────────────────────────────────
// Related section: a line "**Related**" or "**Related:**" followed by
// zero or more [[link]] lines, before any blank line or H2.
const relatedHeaderRe = /^\*\*Related(?::|)\*\*/i;
const relatedHeaderIdx = lines.findIndex(l => relatedHeaderRe.test(l.trim()));

// Fix colon after Related header and split comma-separated inline links
if (relatedHeaderIdx !== -1) {
  const headerLine = lines[relatedHeaderIdx];
  // Strip colon from header
  const fixedHeader = headerLine.replace(/^\*\*Related:\*\*/, '**Related**');
  if (fixedHeader !== headerLine) {
    lines[relatedHeaderIdx] = fixedHeader;
    fixes.push('Removed colon from Related header');
    changed = true;
  }
  // Split comma-separated inline links onto separate lines
  // Pattern: **Related** [[A]], [[B]], [[C]] all on one line
  const inlineLinks = lines[relatedHeaderIdx].match(/\[\[[^\]]+\]\]/g);
  if (inlineLinks && inlineLinks.length > 0) {
    // Remove links from header line, insert as individual lines below
    lines[relatedHeaderIdx] = '**Related**';
    lines.splice(relatedHeaderIdx + 1, 0, ...inlineLinks);
    fixes.push('Split inline Related links onto separate lines');
    changed = true;
  }
}

if (relatedHeaderIdx === -1) {
  // ── Case 1: No Related section — insert after H1 ─────────────────────
  const h1Idx = lines.findIndex(l => /^# /.test(l));
  const insertAfter = h1Idx !== -1 ? h1Idx : -1;

  // Build section content
  const sectionLines = ['', '**Related**'];
  if (projectIndexName) {
    sectionLines.push(`[[${projectIndexName}]]`);
  }

  const insertAt = insertAfter + 1;
  lines.splice(insertAt, 0, ...sectionLines);

  if (projectIndexName) {
    fixes.push(`Inserted Related section with project index link: [[${projectIndexName}]]`);
  } else {
    // Try area file fallback before flagging (same logic as Case 2)
    const areaMapFb = $json.areaMap ?? {};
    const areaSlugFbMatch = fm.match(/^area:\s*(.+)$/m);
    const areaSlugFb = areaSlugFbMatch ? areaSlugFbMatch[1].trim() : null;
    const areaEntryFb = areaSlugFb
      ? Object.values(areaMapFb).find(e => e.slug === areaSlugFb)
      : null;
    if (areaEntryFb) {
      const areaLink = `[[Area \u2013 ${areaEntryFb.displayName}]]`;
      sectionLines.push(areaLink);
      fixes.push(`Inserted Related section with area file link: ${areaLink}`);
    } else {
      fixes.push('Inserted missing Related section header');
      flags.push('Related section is empty — suggest related documents');
    }
  }
  changed = true;

} else {
  // ── Case 2/3: Related section exists — check if it has links ─────────
  // Collect lines that are wikilinks immediately after the header
  let linkCount = 0;
  let insertIdx = relatedHeaderIdx + 1;

  // Skip past any existing link lines to find where the section ends
  while (insertIdx < lines.length) {
    const l = lines[insertIdx].trim();
    if (l.startsWith('[[') && l.endsWith(']]')) {
      linkCount++;
      insertIdx++;
    } else if (l === '') {
      insertIdx++; // allow blank lines within section
    } else {
      break; // hit a heading or content — section is over
    }
  }

  if (linkCount === 0) {
    // Empty section — try to auto-insert project index first
    if (projectIndexName) {
      const link = `[[${projectIndexName}]]`;
      lines.splice(relatedHeaderIdx + 1, 0, link);
      fixes.push(`Added project index link to empty Related section: ${link}`);
      changed = true;
    } else {
      // No project index — try Area file fallback using areaMap
      const areaMap = $json.areaMap ?? {};
      const areaSlugMatch = fm.match(/^area:\s*(.+)$/m);
      const areaSlug = areaSlugMatch ? areaSlugMatch[1].trim() : null;
      // Find matching area entry by slug
      const areaEntry = areaSlug
        ? Object.values(areaMap).find(e => e.slug === areaSlug)
        : null;
      if (areaEntry) {
        const link = `[[Area \u2013 ${areaEntry.displayName}]]`;
        lines.splice(relatedHeaderIdx + 1, 0, link);
        fixes.push(`Added area file link to empty Related section: ${link}`);
        changed = true;
      } else {
        flags.push('Related section is empty — suggest related documents');
      }
    }
  }
  // Case 3: linkCount > 0 — section has links, no action needed
}

return {
  ...$json,
  content: fm + lines.join('\n'),
  fixes,
  flags,
  changed,
};

// ── Whitespace ───────────────────────────────────────────────────────────
// Rules:
//   1. Remove trailing whitespace from all lines
//   2. Ensure H1 is directly after frontmatter with no blank line
//   3. Ensure exactly one blank line between sections (before each H2)
//   4. Ensure exactly one newline at end of file

const raw   = $json.content ?? '';
const fixes = Array.isArray($json.fixes) ? [...$json.fixes] : [];
const flags = Array.isArray($json.flags) ? [...$json.flags] : [];
let changed = $json.changed ?? false;

if (!raw) return { ...$json, fixes, flags, changed };

// Split FM from body
const fmMatch = raw.match(/^---[\r\n][\s\S]*?[\r\n]---[\r\n]/);
const fmEnd   = fmMatch ? fmMatch[0].length : 0;
const fm      = raw.slice(0, fmEnd);
let   body    = raw.slice(fmEnd);

// Rule 1: Strip trailing whitespace from every line in body
const stripped = body.split('\n').map(l => l.trimEnd()).join('\n');
if (stripped !== body) body = stripped;

// Rule 2: H1 must be directly after frontmatter — no leading blank lines
body = body.replace(/^\n+/, '');

// Rule 3: Exactly one blank line immediately before each H2
// Strategy: split into lines, rebuild ensuring one blank line before H2s
// but not stripping blank lines elsewhere (content may need them).
const lines = body.split('\n');
const out   = [];
for (let i = 0; i < lines.length; i++) {
  const line  = lines[i];
  const isH2  = /^## /.test(line);
  if (isH2 && out.length > 0) {
    // Strip any existing blank lines immediately before this H2
    while (out.length > 0 && out[out.length - 1].trim() === '') out.pop();
    // Insert exactly one blank line
    out.push('');
  }
  out.push(line);
  // Rule 3b: Exactly one blank line after H2
  if (isH2) {
    // Skip any blank lines that follow in the source
    while (i + 1 < lines.length && lines[i + 1].trim() === '') i++;
    out.push('');
  }
}
body = out.join('\n');

// Rule 4: Exactly one trailing newline
body = body.replace(/\n*$/, '\n');

const newContent = fm + body;
if (newContent !== raw) {
  changed = true;
  fixes.push('Normalised whitespace (trailing spaces, H1 spacing, H2 blank lines, trailing newline)');
}

return {
  ...$json,
  content: newContent,
  fixes,
  flags,
  changed,
};
